// Written with the help of Claude
// AI Usage Note: generated by Claude Code; verified by manual review of every case against the schema.
import assert from 'node:assert/strict';
import { describe, test } from 'node:test';
import {
  CreateEventBody,
  Event,
  eventExample,
  ListEventsQuery,
  MAX_CATEGORY_IDS,
  MAX_PRICE,
  MAX_RADIUS_KM,
} from '../../dist/api/catalog/schemas/events.js';
import type { NewEvent } from '../../dist/core/catalog/types/event.js';
import { aNewEvent, CATEGORY_ID } from './fixtures/catalog.ts';

const OTHER_CATEGORY_ID = 'c0000000-0000-4000-8000-000000000002';
// Maidan Nezalezhnosti, as the query parser gives it: every value a string.
const POINT = { lat: '50.450', lng: '30.524', radiusKm: '3' };

function issuePaths(query: Record<string, unknown>): PropertyKey[][] {
  const result = ListEventsQuery.safeParse(query);
  if (result.success) assert.fail('expected the query to be rejected');
  return result.error.issues.map((issue: { path: PropertyKey[] }) => issue.path);
}

// FR-010
describe('CreateEventBody', () => {
  const requiredFields = ['title', 'description', 'categoryId', 'venueId', 'startsAt', 'endsAt'] as const;

  for (const field of requiredFields) {
    test(`rejects a body without ${field} and points at ${field}`, () => {
      const body: Partial<NewEvent> = aNewEvent();
      delete body[field];

      const result = CreateEventBody.safeParse(body);

      if (result.success) assert.fail('expected the body to be rejected');
      assert.deepEqual(
        result.error.issues.map((issue: { path: PropertyKey[] }) => issue.path),
        [[field]],
      );
    });
  }

  test('accepts a body with every field filled in', () => {
    const body = aNewEvent();

    const result = CreateEventBody.safeParse(body);

    assert.equal(result.success, true);
    assert.deepEqual(result.data, body);
  });

  test('takes a body without a price as an unknown price', () => {
    const { priceMin: _min, priceMax: _max, ...body } = aNewEvent();

    const result = CreateEventBody.safeParse(body);

    assert.equal(result.success, true);
    assert.deepEqual([result.data?.priceMin, result.data?.priceMax], [null, null]);
  });

  const validPrices = [
    { price: { priceMin: 450, priceMax: null }, title: 'one price' },
    { price: { priceMin: 300, priceMax: 700 }, title: 'a range' },
    { price: { priceMin: 450, priceMax: 450 }, title: 'a range of one price' },
    { price: { priceMin: 0, priceMax: null }, title: 'a free event' },
    { price: { priceMin: 0, priceMax: 500 }, title: 'a range from free' },
    { price: { priceMin: MAX_PRICE, priceMax: MAX_PRICE }, title: 'the highest price' },
  ];
  for (const { price, title } of validPrices) {
    test(`accepts ${title}`, () => {
      const result = CreateEventBody.safeParse(aNewEvent(price));

      assert.equal(result.success, true);
      assert.deepEqual({ priceMin: result.data?.priceMin, priceMax: result.data?.priceMax }, price);
    });
  }

  const invalidPrices = [
    { price: { priceMin: -1 }, field: 'priceMin', title: 'a negative price' },
    { price: { priceMin: 449.5 }, field: 'priceMin', title: 'a price that is not whole hryvnias' },
    { price: { priceMin: '450' }, field: 'priceMin', title: 'a price as a string' },
    { price: { priceMin: MAX_PRICE + 1 }, field: 'priceMin', title: 'a price above the highest' },
    { price: { priceMin: 300, priceMax: 700.5 }, field: 'priceMax', title: 'a highest price that is not whole' },
    { price: { priceMax: 700 }, field: 'priceMax', title: 'a highest price without a lowest one' },
    { price: { priceMin: 700, priceMax: 300 }, field: 'priceMax', title: 'a highest price below the lowest' },
  ];
  for (const { price, field, title } of invalidPrices) {
    test(`rejects ${title} and points at ${field}`, () => {
      const result = CreateEventBody.safeParse({ ...aNewEvent(), ...price });

      if (result.success) assert.fail('expected the body to be rejected');
      assert.deepEqual(
        result.error.issues.map((issue: { path: PropertyKey[] }) => issue.path),
        [[field]],
      );
    });
  }

  // The start and the end of an organization event are always known.
  for (const flag of ['startTimeKnown', 'endTimeKnown'] as const) {
    test(`does not take ${flag}`, () => {
      const result = CreateEventBody.safeParse({ ...aNewEvent(), [flag]: false });

      assert.equal(result.success && flag in result.data, false);
    });
  }
});

describe('Event', () => {
  test('carries an unknown price as null', () => {
    const result = Event.safeParse({ ...eventExample, priceMin: null, priceMax: null });

    assert.equal(result.success, true);
    assert.deepEqual([result.data?.priceMin, result.data?.priceMax], [null, null]);
  });

  const { priceMin: _min, ...withoutPriceMin } = eventExample;
  const { priceMax: _max, ...withoutPriceMax } = eventExample;
  const withoutPrice = [
    { field: 'priceMin', event: withoutPriceMin },
    { field: 'priceMax', event: withoutPriceMax },
  ];
  for (const { field, event } of withoutPrice) {
    test(`rejects an event without ${field} and points at it`, () => {
      const result = Event.safeParse(event);

      if (result.success) assert.fail('expected the event to be rejected');
      assert.deepEqual(
        result.error.issues.map((issue: { path: PropertyKey[] }) => issue.path),
        [[field]],
      );
    });
  }

  const flags = [
    { flag: 'startTimeKnown', title: 'a default start, an exhibition run without opening hours' },
    { flag: 'endTimeKnown', title: 'an event whose provider gives no end' },
  ] as const;
  for (const { flag, title } of flags) {
    test(`carries ${flag}, false for ${title}`, () => {
      const result = Event.safeParse({ ...eventExample, endsAt: '2026-10-17T23:59:59.999+03:00', [flag]: false });

      assert.equal(result.success, true);
      assert.equal(result.data?.[flag], false);
    });

    test(`rejects an event without ${flag} and points at it`, () => {
      const event: Partial<typeof eventExample> = { ...eventExample };
      delete event[flag];

      const result = Event.safeParse(event);

      if (result.success) assert.fail('expected the event to be rejected');
      assert.deepEqual(
        result.error.issues.map((issue: { path: PropertyKey[] }) => issue.path),
        [[flag]],
      );
    });
  }
});

// FR-007
describe('ListEventsQuery', () => {
  const categoryInputs = [
    { title: 'one id', categoryIds: CATEGORY_ID, expected: [CATEGORY_ID] },
    {
      title: 'a repeated parameter',
      categoryIds: [CATEGORY_ID, OTHER_CATEGORY_ID],
      expected: [CATEGORY_ID, OTHER_CATEGORY_ID],
    },
    {
      title: 'a comma-separated list',
      categoryIds: `${CATEGORY_ID},${OTHER_CATEGORY_ID}`,
      expected: [CATEGORY_ID, OTHER_CATEGORY_ID],
    },
  ];
  for (const { title, categoryIds, expected } of categoryInputs) {
    test(`reads the categories from ${title}`, () => {
      const result = ListEventsQuery.safeParse({ categoryIds });

      assert.deepEqual(result.data?.categoryIds, expected);
    });
  }

  const badCategories = [
    { title: 'an id that is not a UUID', categoryIds: 'abc' },
    { title: 'an empty value', categoryIds: '' },
    { title: 'an empty item of a list', categoryIds: `${CATEGORY_ID},` },
    { title: 'more ids than allowed', categoryIds: Array.from({ length: MAX_CATEGORY_IDS + 1 }, () => CATEGORY_ID) },
  ];
  for (const { title, categoryIds } of badCategories) {
    test(`rejects ${title} in categoryIds`, () => {
      assert.ok(issuePaths({ categoryIds }).every((path) => path[0] === 'categoryIds'));
    });
  }

  test(`takes ${MAX_CATEGORY_IDS} categories`, () => {
    const categoryIds = Array.from({ length: MAX_CATEGORY_IDS }, () => CATEGORY_ID);

    assert.equal(ListEventsQuery.safeParse({ categoryIds }).success, true);
  });

  test('reads the point and the radius as numbers', () => {
    const result = ListEventsQuery.safeParse(POINT);

    assert.deepEqual(
      { lat: result.data?.lat, lng: result.data?.lng, radiusKm: result.data?.radiusKm },
      { lat: 50.45, lng: 30.524, radiusKm: 3 },
    );
  });

  const partial = [
    { given: { lat: POINT.lat }, missing: ['lng', 'radiusKm'] },
    { given: { lng: POINT.lng }, missing: ['lat', 'radiusKm'] },
    { given: { lat: POINT.lat, lng: POINT.lng }, missing: ['radiusKm'] },
    { given: { radiusKm: POINT.radiusKm }, missing: ['lat', 'lng'] },
  ];
  for (const { given, missing } of partial) {
    test(`with only ${Object.keys(given).join(' and ')}, points at ${missing.join(' and ')}`, () => {
      assert.deepEqual(
        issuePaths(given),
        missing.map((field) => [field]),
      );
    });
  }

  const outOfRange = [
    { field: 'lat', value: '-90.1' },
    { field: 'lat', value: '90.1' },
    { field: 'lat', value: 'north' },
    { field: 'lng', value: '-180.1' },
    { field: 'lng', value: '180.1' },
    { field: 'radiusKm', value: '0' },
    { field: 'radiusKm', value: '-1' },
    { field: 'radiusKm', value: String(MAX_RADIUS_KM + 0.1) },
  ];
  for (const { field, value } of outOfRange) {
    test(`rejects ${field}=${value}`, () => {
      assert.deepEqual(issuePaths({ ...POINT, [field]: value }), [[field]]);
    });
  }

  test(`takes a radius of ${MAX_RADIUS_KM} km`, () => {
    assert.equal(ListEventsQuery.safeParse({ ...POINT, radiusKm: String(MAX_RADIUS_KM) }).success, true);
  });

  test('takes no point at all', () => {
    const result = ListEventsQuery.safeParse({});

    assert.deepEqual([result.data?.lat, result.data?.lng, result.data?.radiusKm], [undefined, undefined, undefined]);
  });
});
